def circular_minimax_partition(values: list, groups: int) -> int:
    n = len(values)
    if n == 0:
        return 0
    prefix = [0] * (2 * n + 1)
    for i, v in enumerate(values * 2):
        prefix[i + 1] = prefix[i] + v

    def feasible(limit: int) -> bool:
        if max(values) > limit:
            return False
        nxt = [0] * n
        j = 0
        for i in range(n):
            if j < i:
                j = i
            while j < i + n and prefix[j + 1] - prefix[i] <= limit:
                j += 1
            nxt[i] = j
        LOG = (n + 1).bit_length()
        up = [nxt]
        for k in range(1, LOG):
            prev = up[-1]
            cur = [prev[prev[i]] for i in range(n)]
            up.append(cur)
        for start in range(n):
            pos = start
            jumps = 0
            target = start + n
            for k in reversed(range(LOG)):
                if up[k][pos] < target:
                    pos = up[k][pos]
                    jumps += 1 << k
            jumps += 1
            if jumps <= groups:
                return True
        return False
    lo, hi = (max(values), sum(values))
    while lo < hi:
        mid = (lo + hi) // 2
        if feasible(mid):
            hi = mid
        else:
            lo = mid + 1
    return lo

