def two_sum_indices(nums: list, target: int) -> list:
    """
    Return the two original indices whose values sum to target.
    Assume exactly one solution exists. Return indices in increasing order.
    Do not mutate nums.
    """
    index_map = {}
    for i, num in enumerate(nums):
        complement = target - num
        if complement in index_map:
            j = index_map[complement]
            return sorted([i, j])
        index_map[num] = i

