def merge_sorted_arrays(a: list, b: list) -> list:
    """
    Return a new sorted list containing all elements of sorted lists a and b.
    Preserve duplicates and do not mutate either input.
    """
    i, j = (0, 0)
    merged = []
    len_a, len_b = (len(a), len(b))
    while i < len_a and j < len_b:
        if a[i] <= b[j]:
            merged.append(a[i])
            i += 1
        else:
            merged.append(b[j])
            j += 1
    if i < len_a:
        merged.extend(a[i:])
    if j < len_b:
        merged.extend(b[j:])
    return merged

