def valid_parentheses(s: str) -> bool:
    """
    Return True exactly when s contains properly nested and matched
    parentheses using (), [], and {}. Every character in s is one of
    these six bracket characters.
    """
    pairs = {')': '(', ']': '[', '}': '{'}
    stack = []
    for ch in s:
        if ch in pairs.values():
            stack.append(ch)
        else:
            if not stack or stack[-1] != pairs[ch]:
                return False
            stack.pop()
    return not stack

