def best_time_stock(prices: list) -> int:
    """
    Return the maximum profit from one buy followed by one sell. The buy
    must occur before the sell. Return 0 when no positive profit exists.
    """
    if not prices:
        return 0
    min_price = prices[0]
    max_profit = 0
    for price in prices[1:]:
        if price < min_price:
            min_price = price
        else:
            profit = price - min_price
            if profit > max_profit:
