def evaluate_rpn(tokens: list) -> int:
    """
    Evaluate an expression in Reverse Polish Notation. Tokens are integers
    or +, -, *, /. Division truncates toward zero. The expression is valid.
    """
    stack = []
    for token in tokens:
        if isinstance(token, int):
            stack.append(token)
        else:
            b = stack.pop()
            a = stack.pop()
            if token == '+':
                stack.append(a + b)
            elif token == '-':
                stack.append(a - b)
            elif token == '*':
                stack.append(a * b)
            elif token == '/':
                stack.append(int(a / b))
    return stack[-1]

