def search_rotated_array(nums: list, target: int) -> int:
    """
    nums is a rotated sorted array with distinct values. Return the index of
    target or -1 if absent.
    """
    low, high = (0, len(nums) - 1)
    while low <= high:
        mid = (low + high) // 2
        if nums[mid] == target:
            return mid
        if nums[low] <= nums[mid]:
            if nums[low] <= target < nums[mid]:
                high = mid - 1
            else:
                low = mid + 1
        elif nums[mid] < target <= nums[high]:
            low = mid + 1
        else:
            high = mid - 1
    return -1

