def climb_stairs(n: int) -> int:
    """
    Starting at step 0, return the number of distinct ways to reach step n
    when each move is either 1 or 2 steps. n >= 0.
    """
    if n < 0:
        raise ValueError('n must be non-negative')
    if n == 0 or n == 1:
        return 1
    a, b = (1, 1)
    for _ in range(2, n + 1):
        a, b = (b, a + b)
    return b

