def coin_change_min(coins: list, amount: int) -> int:
    """
    Return the minimum number of coins needed to make amount, using unlimited
    copies of the given positive coin denominations. Return -1 if impossible.
    """
    if amount < 0:
        return -1
    if amount == 0:
        return 0
    INF = amount + 1
    dp = [INF] * (amount + 1)
    dp[0] = 0
    for coin in coins:
        if coin <= 0:
            continue
        for i in range(coin, amount + 1):
            if dp[i - coin] + 1 < dp[i]:
                dp[i] = dp[i - coin] + 1
    return dp[amount] if dp[amount] != INF else -1

