def longest_increasing_subsequence(nums: list) -> int:
    """
    Return the length of a strictly increasing subsequence. Elements need not
    be contiguous.
    """
    import bisect
    if not nums:
        return 0
    tails = []
    for x in nums:
        idx = bisect.bisect_left(tails, x)
        if idx == len(tails):
            tails.append(x)
        else:
            tails[idx] = x
    return len(tails)

