def decode_ways(s: str) -> int:
    """
    Digits encode letters where 1=A through 26=Z. Return the number of
    possible decodings. A leading zero or invalid zero placement is invalid.
    """
    if not s:
        return 0
    n = len(s)
    if s[0] == '0':
        return 0
    prev2 = 1
    prev1 = 1
    for i in range(1, n):
        curr = 0
        if s[i] != '0':
            curr += prev1
        two_digit = int(s[i - 1:i + 1])
        if 10 <= two_digit <= 26:
            curr += prev2
        if curr == 0:
            return 0
        prev2, prev1 = (prev1, curr)
    return prev1

