def subset_sum_exists(nums: list, target: int) -> bool:
    """
    Return True if some subset of nums sums exactly to target. Each input
    element may be used at most once. nums contains non-negative integers.
    """
    if target == 0:
        return True
    if target < 0:
        return False
    reachable = {0}
    for num in nums:
        if num > target:
            continue
        new_sums = set()
        for s in reachable:
            ns = s + num
            if ns == target:
                return True
            if ns < target:
                new_sums.add(ns)
        reachable.update(new_sums)
    return target in reachable

