def count_islands(grid: list) -> int:
    """
    grid contains '1' land and '0' water. Count connected land components
    using four-directional adjacency. Do not mutate the input.
    """
    if not grid:
        return 0
    rows = len(grid)
    cols = len(grid[0]) if rows else 0
    visited = set()
    count = 0
    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == '1' and (i, j) not in visited:
                count += 1
                stack = [(i, j)]
                while stack:
                    x, y = stack.pop()
                    if (x, y) in visited:
                        continue
                    visited.add((x, y))
                    for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        nx, ny = (x + dx, y + dy)
                        if 0 <= nx < rows and 0 <= ny < cols:
                            if grid[nx][ny] == '1' and (nx, ny) not in visited:
                                stack.append((nx, ny))
    return count

