def network_delay_time(times: list, n: int, k: int) -> int:
    from heapq import heappush, heappop
    INF = float('inf')
    graph = [[] for _ in range(n + 1)]
    for u, v, w in times:
        graph[u].append((v, w))
    dist = [INF] * (n + 1)
    dist[k] = 0
    heap = [(0, k)]
    while heap:
        d, u = heappop(heap)
        if d != dist[u]:
            continue
        for v, w in graph[u]:
            nd = d + w
            if nd < dist[v]:
                dist[v] = nd
                heappush(heap, (nd, v))
    max_dist = max(dist[1:])
    return -1 if max_dist == INF else int(max_dist)

