def minimum_spanning_tree_weight(n: int, edges: list) -> int:
    """
    edges contains undirected [u,v,w] edges with vertices 0..n-1. Return the
    minimum total weight of a spanning tree. The graph is guaranteed connected.
    """
    if n <= 1:
        return 0
    parent = list(range(n))
    rank = [0] * n

    def find(x: int) -> int:
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(x: int, y: int) -> bool:
        rx, ry = (find(x), find(y))
        if rx == ry:
            return False
        if rank[rx] < rank[ry]:
            parent[rx] = ry
        elif rank[rx] > rank[ry]:
            parent[ry] = rx
        else:
            parent[ry] = rx
            rank[rx] += 1
        return True
    edges.sort(key=lambda e: e[2])
    total = 0
    edges_used = 0
    for u, v, w in edges:
        if union(u, v):
            total += w
            edges_used += 1
            if edges_used == n - 1:
                break
    return total

