def bipartite_graph(graph: list) -> bool:
    """
    graph[i] lists neighbors of vertex i in an undirected graph. Return True
    if the graph is bipartite.
    """
    from collections import deque
    n = len(graph)
    color = [-1] * n
    for start in range(n):
        if color[start] != -1:
            continue
        color[start] = 0
        q = deque([start])
        while q:
            v = q.popleft()
            for u in graph[v]:
                if u < 0 or u >= n:
                    return False
                if color[u] == -1:
                    color[u] = 1 - color[v]
                    q.append(u)
                elif color[u] == color[v]:
                    return False
    return True

