    """
    Serialize a binary tree represented in level order using None. Return a
    comma-separated preorder representation using '#' for missing children.
    """
    if not values or values[0] is None:
        return ''

    class Node:
        __slots__ = ('val', 'left', 'right')

        def __init__(self, val):
            self.val = val
            self.left = None
            self.right = None
    root = Node(values[0])
    queue = [root]
    idx = 1
    while idx < len(values):
        current = queue.pop(0)
        if idx < len(values):
            val = values[idx]
            idx += 1
            if val is not None:
                current.left = Node(val)
                queue.append(current.left)
        if idx < len(values):
            val = values[idx]
            idx += 1
            if val is not None:
                current.right = Node(val)
                queue.append(current.right)
    result = []

    def preorder(node):
        if node is None:
            result.append('#')
            return
        result.append(str(node.val))
        preorder(node.left)
        preorder(node.right)
    preorder(root)
    return ','.join(result)

