def minimum_path_sum(grid: list) -> int:
    """
    Return the minimum sum from top-left to bottom-right moving only right or
    down. Grid values are nonnegative.
    """
    if not grid or not grid[0]:
        return 0
    rows, cols = (len(grid), len(grid[0]))
    for i in range(rows):
        for j in range(cols):
            if i == 0 and j == 0:
                continue
            if i == 0:
                grid[i][j] += grid[i][j - 1]
            elif j == 0:
                grid[i][j] += grid[i - 1][j]
            else:
                grid[i][j] += min(grid[i - 1][j], grid[i][j - 1])
    return grid[rows - 1][cols - 1]

