def minimum_window_substring(s: str, t: str) -> str:
    from collections import Counter
    if not t or not s:
        return ''
    t_counts = Counter(t)
    required = len(t_counts)
    window_counts = {}
    formed = 0
    left = 0
    best_len = float('inf')
    best_start = 0
    for right, char in enumerate(s):
        window_counts[char] = window_counts.get(char, 0) + 1
        if char in t_counts and window_counts[char] == t_counts[char]:
            formed += 1
        while left <= right and formed == required:
            window_len = right - left + 1
            if window_len < best_len:
                best_len = window_len
                best_start = left
            left_char = s[left]
            window_counts[left_char] -= 1
            if left_char in t_counts and window_counts[left_char] < t_counts[left_char]:
                formed -= 1
            left += 1
    return s[best_start:best_start + best_len] if best_len != float('inf') else ''

