def string_compression(s: str) -> str:
    """
    Replace each maximal run of the same character by character followed by
    its count. For a run of length 1, still include count 1.
    """
    if not s:
        return ''
    result = []
    current_char = s[0]
    count = 1
    for ch in s[1:]:
        if ch == current_char:
            count += 1
        else:
            result.append(f'{current_char}{count}')
            current_char = ch
            count = 1
    result.append(f'{current_char}{count}')
    return ''.join(result)

