def reorganize_string(s: str) -> str:
    from collections import Counter
    freq = Counter(s)
    n = len(s)
    if n == 0:
        return ''
    if max(freq.values()) > (n + 1) // 2:
        return ''
    result = []
    prev = None
    for i in range(n):
        for c in sorted(freq):
            if freq[c] == 0 or c == prev:
                continue
            freq[c] -= 1
            remaining = n - i - 1
            max_rem = max(freq.values()) if freq else 0
            if max_rem <= (remaining + 1) // 2:
                result.append(c)
                prev = c
                break
            freq[c] += 1
        else:
            return ''
    return ''.join(result)

