def lru_cache_simulation(capacity: int, operations: list) -> list:
    from collections import OrderedDict
    if capacity <= 0:
        return [-1 for op in operations if op[0] == 'get']
    cache = OrderedDict()
    outputs = []
    for op in operations:
        if op[0] == 'put':
            _, key, value = op
            if key in cache:
                cache.pop(key)
            elif len(cache) == capacity:
                cache.popitem(last=False)
            cache[key] = value
        elif op[0] == 'get':
            _, key = op
            if key in cache:
                value = cache.pop(key)
                cache[key] = value
                outputs.append(value)
            else:
                outputs.append(-1)
    return outputs

