def daily_stock_span(prices: list) -> list:
    """
    For each price, return the number of consecutive previous days, including
    today, whose price was less than or equal to today's price.
    """
    if not prices:
        return []
    spans = [0] * len(prices)
    stack = []
    for i, price in enumerate(prices):
        while stack and prices[stack[-1]] <= price:
            stack.pop()
        if not stack:
            spans[i] = i + 1
        else:
            spans[i] = i - stack[-1]
        stack.append(i)
    return spans

